<?php
namespace ServSys\Admin;
use ServSys\Customers\CustomerRepository;
use ServSys\Sites\SiteRepository;
use ServSys\Equipment\EquipmentRepository;
use ServSys\PreventiveMaintenance\PMAgreementRepository;
use ServSys\PreventiveMaintenance\PMAgreementEquipmentRepository;
use ServSys\PreventiveMaintenance\PMAgreementService;
use ServSys\PreventiveMaintenance\PMPlanRepository;
use ServSys\PreventiveMaintenance\PMPlanTermRepository;
use ServSys\PreventiveMaintenance\PMScheduledVisitRepository;
use ServSys\PreventiveMaintenance\PMScheduledVisitService;
use ServSys\ServiceCalls\ServiceCallRepository;
use ServSys\Users\Capabilities;
if(!defined('ABSPATH')){exit;}
final class PMAgreementsPage {
 public function register(): void {add_action('admin_menu',array($this,'register_menu'));add_action('admin_post_servsys_save_pm_agreement',array($this,'save'));add_action('admin_post_servsys_save_pm_visit',array($this,'save_visit'));add_action('admin_post_servsys_delete_pm_visit',array($this,'delete_visit'));}
 public function register_menu(): void {add_submenu_page('servsys','PM Agreements','PM Agreements',Capabilities::VIEW_PM_AGREEMENTS,'servsys-pm-agreements',array($this,'render'));}
 public function render(): void {if(!current_user_can(Capabilities::VIEW_PM_AGREEMENTS)){wp_die(esc_html__('You do not have permission to view PM Agreements.','servsys'));}/* phpcs:disable WordPress.Security.NonceVerification.Recommended -- Read-only navigation/search. */$edit=isset($_GET['edit'])?absint(wp_unslash($_GET['edit'])):0;$term=isset($_GET['s'])?sanitize_text_field(wp_unslash($_GET['s'])):'';$customer_id=isset($_GET['customer_id'])?absint(wp_unslash($_GET['customer_id'])):0;$site_id=isset($_GET['site_id'])?absint(wp_unslash($_GET['site_id'])):0;$error=isset($_GET['servsys_error'])?sanitize_text_field(wp_unslash($_GET['servsys_error'])):'';
/* phpcs:enable WordPress.Security.NonceVerification.Recommended */$repo=new PMAgreementRepository();echo '<div class="wrap"><h1>Preventive Maintenance Agreements</h1>';if($error){echo '<div class="notice notice-error inline"><p>'.esc_html($error).'</p></div>';}echo '<form method="get"><input type="hidden" name="page" value="servsys-pm-agreements"><p class="search-box"><input type="search" name="s" value="'.esc_attr($term).'"> ';submit_button('Search Agreements','secondary','',false);echo '</p></form><table class="widefat striped"><thead><tr><th>Customer</th><th>Site</th><th>Plan</th><th>Term</th><th>Price</th><th>Dates</th><th>Visits/Year</th><th>Status</th><th>Action</th></tr></thead><tbody>';foreach($repo->search($term) as $row){echo '<tr><td>'.esc_html($row['customer_name']).'</td><td>'.esc_html($row['site_name']?:$row['site_address']).'</td><td>'.esc_html($row['plan_description_snapshot']).'</td><td>'.esc_html($row['term_months']).' months</td><td>$'.esc_html(number_format((float)$row['contract_price'],2)).'</td><td>'.esc_html($row['start_date'].' — '.$row['end_date']).'</td><td>'.esc_html($row['visits_per_year']).'</td><td>'.esc_html(ucfirst($row['status'])).'</td><td>';if(current_user_can(Capabilities::MANAGE_PM_AGREEMENTS)){echo '<a class="button button-small" href="'.esc_url(admin_url('admin.php?page=servsys-pm-agreements&edit='.(int)$row['id'])).'">Edit</a>';}echo '</td></tr>';}echo '</tbody></table>';if(current_user_can(Capabilities::MANAGE_PM_AGREEMENTS)){$this->render_form($edit?$repo->find($edit):null,$customer_id,$site_id);}echo '</div>';}
 private function render_form($agreement,int $pref_customer,int $pref_site): void {$a=wp_parse_args($agreement?:array(),array('id'=>0,'customer_id'=>$pref_customer,'site_id'=>$pref_site,'pm_plan_id'=>0,'agreement_date'=>'','start_date'=>'','end_date'=>'','term_months'=>0,'visits_per_year'=>2,'additional_services'=>'','notes'=>'','status'=>'active'));$customers=(new CustomerRepository())->search('',true);$sites=$a['customer_id']?(new SiteRepository())->for_customer((int)$a['customer_id'],true):array();$equipment=$a['site_id']?(new EquipmentRepository())->for_site((int)$a['site_id'],true):array();$covered=array();if($a['id']){foreach((new PMAgreementEquipmentRepository())->for_agreement((int)$a['id']) as $row){$covered[]=(int)$row['equipment_id'];}}$plans=(new PMPlanRepository())->search('',true);echo '<h2>'.($a['id']?'Edit':'Add').' PM Agreement</h2><p>Choose Customer and save/reopen if you need to populate its Site list; choose Site and save/reopen to populate covered Equipment. The selected PM Plan term price is snapshotted when saved.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_save_pm_agreement');echo '<input type="hidden" name="action" value="servsys_save_pm_agreement"><input type="hidden" name="agreement_id" value="'.esc_attr((string)$a['id']).'"><p><label>Customer<br><select name="customer_id" required><option value="">Select Customer</option>';foreach($customers as $c){echo '<option value="'.esc_attr((string)$c['id']).'" '.selected((int)$a['customer_id'],(int)$c['id'],false).'>'.esc_html($c['name']).'</option>';}echo '</select></label></p><p><label>Site<br><select name="site_id" required><option value="">Select Site</option>';foreach($sites as $s){echo '<option value="'.esc_attr((string)$s['id']).'" '.selected((int)$a['site_id'],(int)$s['id'],false).'>'.esc_html($s['name']?:$s['address1']).'</option>';}echo '</select></label></p><p><label>PM Plan / Term<br><select name="pm_plan_term" required><option value="">Select Plan / Term</option>';$termrepo=new PMPlanTermRepository();foreach($plans as $p){foreach($termrepo->for_plan((int)$p['id']) as $t){$value=$p['id'].':'.$t['term_months'];$selected=(int)$a['pm_plan_id']===(int)$p['id']&&(int)$a['term_months']===(int)$t['term_months'];echo '<option value="'.esc_attr($value).'" '.selected($selected,true,false).'>'.esc_html($p['description'].' — '.$t['term_months'].' months — $'.number_format((float)$t['price'],2)).'</option>';}}echo '</select></label></p>';foreach(array('agreement_date'=>'Agreement Date','start_date'=>'Start Date','end_date'=>'End Date') as $name=>$label){echo '<p><label>'.esc_html($label).'<br><input type="date" name="'.esc_attr($name).'" value="'.esc_attr($a[$name]).'" '.('agreement_date'===$name?'':'required').'></label></p>';}echo '<p><label>Visits per Year<br><input type="number" min="0" name="visits_per_year" value="'.esc_attr((string)$a['visits_per_year']).'" required></label></p><p><label>Status<br><select name="status">';foreach(array('active'=>'Active','expired'=>'Expired','cancelled'=>'Cancelled') as $value=>$label){echo '<option value="'.esc_attr($value).'" '.selected($a['status'],$value,false).'>'.esc_html($label).'</option>';}echo '</select></label></p><p><label>Additional Services<br><textarea class="large-text" rows="3" name="additional_services">'.esc_textarea($a['additional_services']).'</textarea></label></p><p><label>Notes<br><textarea class="large-text" rows="4" name="notes">'.esc_textarea($a['notes']).'</textarea></label></p><h3>Covered Equipment</h3>';if(!$equipment){echo '<p>No equipment is available until a valid Site is selected.</p>';}else{foreach($equipment as $e){$label=trim($e['equipment_type'].' '.$e['brand'].' '.$e['model_number'].' '.$e['serial_number']);echo '<label style="display:block"><input type="checkbox" name="equipment_ids[]" value="'.esc_attr((string)$e['id']).'" '.checked(in_array((int)$e['id'],$covered,true),true,false).'> '.esc_html($label).'</label>';}}submit_button($a['id']?'Save PM Agreement':'Add PM Agreement');echo '</form>';if($a['id']){$this->render_visits($a);}}
 private function render_visits(array $agreement): void {$repo=new PMScheduledVisitRepository();$calls=(new ServiceCallRepository())->for_site((int)$agreement['customer_id'],(int)$agreement['site_id'],100);echo '<hr><h3>Scheduled PM Visits</h3><p>Month/year is the authoritative planned period. Enter an exact date only when one has actually been scheduled.</p><table class="widefat striped"><thead><tr><th>Planned Period</th><th>Exact Date</th><th>Service Call</th><th>Status</th><th>Notes</th><th>Action</th></tr></thead><tbody>';foreach($repo->for_agreement((int)$agreement['id']) as $v){echo '<tr><td>'.esc_html(sprintf('%02d/%04d',$v['scheduled_month'],$v['scheduled_year'])).'</td><td>'.esc_html($v['scheduled_date']?:'—').'</td><td>'.esc_html($v['service_call_id']?'#'.$v['service_call_id']:'—').'</td><td>'.esc_html(ucfirst($v['status'])).'</td><td>'.esc_html($v['notes']).'</td><td>';if(empty($v['service_call_id'])){$url=wp_nonce_url(admin_url('admin-post.php?action=servsys_delete_pm_visit&agreement_id='.(int)$agreement['id'].'&visit_id='.(int)$v['id']),'servsys_delete_pm_visit_'.$v['id']);echo '<a class="button button-small" href="'.esc_url($url).'">Delete</a>';}echo '</td></tr>';}echo '</tbody></table><h4>Add Scheduled Visit</h4><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_save_pm_visit');echo '<input type="hidden" name="action" value="servsys_save_pm_visit"><input type="hidden" name="agreement_id" value="'.esc_attr((string)$agreement['id']).'"><p><label>Scheduled Month <input type="number" min="1" max="12" name="scheduled_month" required></label> <label>Year <input type="number" min="1900" max="2200" name="scheduled_year" required></label></p><p><label>Exact Date (optional)<br><input type="date" name="scheduled_date"></label></p><p><label>Service Call (optional)<br><select name="service_call_id"><option value="">Not linked</option>';foreach($calls as $call){echo '<option value="'.esc_attr((string)$call['id']).'">'.esc_html(($call['call_number']?:'#'.$call['id']).' — '.$call['service_date'].' — '.ucfirst($call['status'])).'</option>';}echo '</select></label></p><p><label>Status<br><select name="status"><option value="scheduled">Scheduled</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label></p><p><label>Notes<br><textarea class="large-text" rows="2" name="notes"></textarea></label></p>';submit_button('Add Scheduled Visit','secondary');echo '</form>';}
 public function save_visit(): void {check_admin_referer('servsys_save_pm_visit');if(!current_user_can(Capabilities::MANAGE_PM_AGREEMENTS)){wp_die(esc_html__('Permission denied.','servsys'));}$agreement_id=isset($_POST['agreement_id'])?absint(wp_unslash($_POST['agreement_id'])):0;try{(new PMScheduledVisitService())->save($agreement_id,wp_unslash($_POST));$url=admin_url('admin.php?page=servsys-pm-agreements&edit='.$agreement_id);}catch(\InvalidArgumentException|\RuntimeException $e){$url=add_query_arg('servsys_error',$e->getMessage(),admin_url('admin.php?page=servsys-pm-agreements&edit='.$agreement_id));}wp_safe_redirect($url);exit;}
 public function delete_visit(): void {$agreement_id=isset($_GET['agreement_id'])?absint(wp_unslash($_GET['agreement_id'])):0;$visit_id=isset($_GET['visit_id'])?absint(wp_unslash($_GET['visit_id'])):0;check_admin_referer('servsys_delete_pm_visit_'.$visit_id);if(!current_user_can(Capabilities::MANAGE_PM_AGREEMENTS)){wp_die(esc_html__('Permission denied.','servsys'));}try{(new PMScheduledVisitService())->delete($agreement_id,$visit_id);$url=admin_url('admin.php?page=servsys-pm-agreements&edit='.$agreement_id);}catch(\InvalidArgumentException|\RuntimeException $e){$url=add_query_arg('servsys_error',$e->getMessage(),admin_url('admin.php?page=servsys-pm-agreements&edit='.$agreement_id));}wp_safe_redirect($url);exit;}
 public function save(): void {check_admin_referer('servsys_save_pm_agreement');if(!current_user_can(Capabilities::MANAGE_PM_AGREEMENTS)){wp_die(esc_html__('Permission denied.','servsys'));}$id=isset($_POST['agreement_id'])?absint(wp_unslash($_POST['agreement_id'])):0;$data=wp_unslash($_POST);$parts=isset($data['pm_plan_term'])?explode(':',(string)$data['pm_plan_term'],2):array();$data['pm_plan_id']=isset($parts[0])?absint($parts[0]):0;$data['term_months']=isset($parts[1])?absint($parts[1]):0;try{$service=new PMAgreementService();$id=$service->save($data,$id);$service->replace_equipment($id,isset($data['equipment_ids'])?(array)$data['equipment_ids']:array());$url=admin_url('admin.php?page=servsys-pm-agreements&edit='.$id);}catch(\InvalidArgumentException|\RuntimeException $e){$url=add_query_arg('servsys_error',$e->getMessage(),admin_url('admin.php?page=servsys-pm-agreements'.($id?'&edit='.$id:'')));}wp_safe_redirect($url);exit;}
}
